  "badm.contact": "Support contact shown on the payment page",
  "badm.saved": "Saved.",
  "badm.webhookTitle": "Payment webhook",
  "badm.webhookDesc": "The transaction checker pushes incoming transfers to POST /api/v1/billing/payments/webhook with this secret; a transfer carrying an order code and the full amount confirms the order automatically.",
  "badm.webhookSecret": "Secret",
  "badm.webhookOff": "Off",
  "badm.webhookGenerate": "Generate new secret",
  "badm.webhookDisable": "Turn off",
  "badm.webhookRegenConfirm": "Generate a new secret? The old one stops working at once; update the checker right away.",
  "badm.webhookOffConfirm": "Turn the payment webhook off? Transfers pushed after this are refused until a new secret is generated.",
  "badm.webhookShownOnce": "Copy this secret now and give it to the checker over a safe channel. It is not shown again.",
  "badm.webhookCopy": "Copy",
  "badm.webhookCopied": "Copied",
  "badm.webhookHelp": "Header X-Webhook-Secret: <secret>. Takes effect immediately, no restart.",
  "bwg.title": "Integration guide",
  "bwg.setupTitle": "Setup",
  "bwg.step1": "Fill in the receiving bank account above and save. Without an account number the purchase page shows only prices.",
  "bwg.step2": "Click \"Generate new secret\", copy it and hand it to the transaction checker over a safe channel (not ordinary chat or e-mail). It is shown once; afterwards only its last 4 characters are visible, enough to compare with the checker's copy.",
  "bwg.step3": "Check that the secret works: an empty request with it must get 400 (secret accepted, body refused, nothing recorded).",
  "bwg.checkButton": "Check the new secret",
  "bwg.checkOk": "Secret accepted. The webhook is on.",
  "bwg.checkWrong": "Secret refused (401). Generate a new one and try again.",
  "bwg.checkLimited": "Too many attempts from this IP (429). Retry after {seconds} seconds.",
  "bwg.checkOff": "The webhook is off (503).",
  "bwg.checkOther": "Unexpected answer; see the backend log.",
  "bwg.checkNeedsSecret": "Generate a secret first; the check appears while it is shown.",
  "bwg.checkNeedsNewSecret": "The check needs the full secret, which is shown only right after it is generated. From the checker's side: send {} with the secret and expect 400.",
  "bwg.step4": "Point the checker at the endpoint below. It pushes each incoming transfer as one request; a transfer whose content carries a pending order code (WR…) and the full amount confirms the order and activates the package at once.",
  "bwg.requestTitle": "Request the checker sends",
  "bwg.requestDesc": "One request per transaction, JSON body up to 64 KB:",
  "bwg.requestAuth": "Instead of X-Webhook-Secret the checker may send Authorization: Bearer <secret> or Authorization: Apikey <secret> (SePay's form). No user login is needed.",
  "bwg.fieldsTitle": "Fields",
  "bwg.colField": "Field",
  "bwg.colRequired": "Required",
  "bwg.colNote": "Notes",
  "bwg.yes": "yes",
  "bwg.fieldSource": "Name of the pushing service (letters, digits, -_. up to 32 characters); keep it fixed.",
  "bwg.fieldTxId": "The bank's transaction id (up to 128 characters). The same source + transaction_id sent again is not processed twice.",
  "bwg.fieldAmount": "Amount in đồng as a JSON integer; 199000.0 or \"199000\" get 400. Missing or ≤ 0 is stored as ignored.",
  "bwg.fieldContent": "The transfer content verbatim; the order code is found even in upper case or run into the next word.",
  "bwg.fieldAccount": "Receiving account; when sent and different from the configured one, the transaction is ignored.",
  "bwg.fieldDirection": "in (default) or out; outgoing money is ignored.",
  "bwg.fieldTime": "When the bank recorded it (RFC 3339). Recommended: a transfer made before the deadline but reported after the order expired reopens the order only when this time is sent.",
  "bwg.codesTitle": "Answers and what the checker should do",
  "bwg.colCode": "Code",
  "bwg.colAction": "Meaning → action",
  "bwg.code200": "Recorded, matched or not (see data.transaction.status) → done.",
  "bwg.code400": "Bad body (missing source/transaction_id, wrong types, direction not in/out, NUL bytes, over 64 KB) → log and alert; resending unchanged fails again.",
  "bwg.code401": "Wrong or missing secret → keep the transaction, alert; resend after fixing the secret.",
  "bwg.code429": "Rate limit → wait the Retry-After seconds and resend; never drop the transaction.",
  "bwg.code500": "Storage error, nothing recorded → resend with backoff.",
  "bwg.code503": "Webhook off → keep the transaction and resend later.",
  "bwg.retryNote": "Resending is always safe: a repeat returns the stored result with duplicate: true. Keep a queue of transactions without a 200 and remove one only when it gets a 200.",
  "bwg.statusTitle": "Transaction statuses",
  "bwg.colStatus": "Status",
  "bwg.colMeaning": "Meaning → what the SuperAdmin does",
  "bwg.stMatched": "Order confirmed automatically; reason notes an overpayment → refund the excess if needed.",
  "bwg.stUnmatched": "No known order code in the content → find the order by amount and time, confirm it by hand in Orders above.",
  "bwg.stUnderpaid": "Right order, amount short → ask the buyer to pay the rest, then confirm by hand.",
  "bwg.stClosed": "Order already paid or cancelled, or the money came after expiry → refund, or create a new order and confirm it.",
  "bwg.stFailed": "Matched but could not be applied (e.g. the current package has more seats) → read reason; usually cancel and let the buyer reorder.",
  "bwg.stIgnored": "Outgoing money, amount ≤ 0, or another account → nothing.",
  "bwg.listNote": "Transfers that did not confirm an order: GET /api/v1/system/admin/usage/payments?status=unmatched&page=1&page_size=50 with a SuperAdmin token (newest first; leave out status for all).",
  "bwg.securityTitle": "Security",
  "bwg.secRotate": "One secret at a time. To rotate: stop the checker → Generate new secret → give it the new secret → start it again. A checker left running with the old secret is blocked after 10 failures.",
  "bwg.secLimits": "Per caller IP: 300 requests/minute (429, Retry-After: 60); 10 wrong secrets in 15 minutes block that IP for 15 minutes even with the right secret (429, Retry-After: 900). Requests without any secret get 401 and are not counted.",
  "bwg.secLeak": "Whoever holds the secret can activate packages. Treat it like an admin password; if it may have leaked, generate a new one at once and review the transactions by source. Every change is in the audit log (without the value).",
  "bwg.deployTitle": "Once per deployment: the caller's IP",
  "bwg.deployDesc": "The IP limits need the backend to see the real caller IP. This is infrastructure read at start-up, so it stays in the server's .env (docker compose only; leave it unset on helm/k8s):",
  "bwg.deploySteps": "Find the subnet with docker network inspect <project>_WeKnora-network, then recreate the app container (docker compose up -d --force-recreate app). Check: open the site from a LAN machine and look for its IP in client_ip of the app log; if every request shows the same 172.x/192.168.x address the subnet is wrong. Behind another load balancer/TLS proxy also set REAL_IP_FROM=<LB IP or CIDR> and recreate the frontend container instead (docker compose up -d --force-recreate frontend).",
  "bwg.fullGuide": "Full guide with troubleshooting: docs/billing-payment-webhook.md in the source repository.",
  "usg.planLimits": "Limits",
  "usg.planOrder": "Order",
  "usg.planActive": "Active (assignable)",
  "usg.addLimit": "Add limit",
  "usg.limitZeroHint": "0 = unlimited. Day and month follow the Vietnam calendar.",
  "usg.metricQuestions": "questions",
  "usg.metricTokens": "tokens",
  "usg.periodDay": "day",
  "usg.periodMonth": "month",
