  "bwg.step2": "Bấm \"Tạo khóa mới\", chép khóa và giao cho dịch vụ kiểm tra giao dịch qua kênh an toàn (không gửi qua chat/email thường). Khóa chỉ hiện một lần; sau đó chỉ còn 4 ký tự cuối, đủ để đối chiếu với khóa dịch vụ đang dùng.",
  "bwg.step3": "Kiểm tra khóa: gửi request rỗng kèm khóa phải nhận 400 (khóa đúng, body bị từ chối, không ghi gì).",
