  "bwg.step4": "Cấu hình dịch vụ kiểm tra gọi tới địa chỉ dưới đây, mỗi giao dịch tiền vào một request. Giao dịch có mã đơn đang chờ (WR…) trong nội dung và đủ tiền sẽ xác nhận đơn và kích hoạt gói ngay.",
