  "bwg.code500": "Lỗi lưu trữ, chưa ghi gì → gửi lại, giãn dần.",
  "bwg.code503": "Webhook đang tắt → giữ giao dịch, gửi lại sau.",
  "bwg.retryNote": "Gửi lại luôn an toàn: lần sau trả kết quả đã lưu với duplicate: true. Dịch vụ nên giữ hàng đợi các giao dịch chưa nhận 200 và chỉ xóa khỏi hàng đợi khi nhận 200.",
  "bwg.statusTitle": "Trạng thái giao dịch",
  "bwg.colStatus": "Trạng thái",
  "bwg.colMeaning": "Nghĩa → SuperAdmin làm gì",
  "bwg.stMatched": "Đã tự xác nhận đơn; reason ghi nếu chuyển dư → hoàn phần dư nếu cần.",
  "bwg.stUnmatched": "Nội dung không có mã đơn hợp lệ → tìm đơn theo số tiền và thời điểm, bấm Xác nhận ở mục Đơn hàng phía trên.",
  "bwg.stUnderpaid": "Đúng đơn nhưng chuyển thiếu → liên hệ người mua chuyển thêm, rồi xác nhận tay.",
  "bwg.stClosed": "Đơn đã thanh toán/hủy, hoặc tiền đến sau hạn → hoàn tiền, hoặc tạo đơn mới rồi xác nhận.",
  "bwg.stFailed": "Khớp đơn nhưng không áp dụng được (vd. gói hiện có nhiều ghế hơn) → đọc reason; thường hủy đơn để người mua đặt lại.",
  "bwg.stIgnored": "Tiền ra, số tiền ≤ 0 hoặc tài khoản khác → không cần làm gì.",
  "bwg.listNote": "Giao dịch chưa xác nhận được đơn: GET /api/v1/system/admin/usage/payments?status=unmatched&page=1&page_size=50 với token SuperAdmin (mới nhất trước; bỏ status để xem tất cả).",
  "bwg.securityTitle": "Bảo mật",
  "bwg.secRotate": "Mỗi lúc chỉ có một khóa. Đổi khóa theo thứ tự: dừng dịch vụ kiểm tra → Tạo khóa mới → cập nhật khóa cho dịch vụ → chạy lại. Để dịch vụ chạy với khóa cũ sẽ bị chặn sau 10 lần sai.",
  "bwg.secLimits": "Theo IP bên gọi: 300 request/phút (429, Retry-After: 60); sai khóa 10 lần trong 15 phút thì IP đó bị chặn 15 phút, kể cả khi gửi khóa đúng (429, Retry-After: 900). Request không gửi khóa chỉ nhận 401, không bị tính.",
  "bwg.secLeak": "Ai có khóa đều kích hoạt được gói. Giữ khóa như mật khẩu quản trị; nghi lộ thì tạo khóa mới ngay và rà các giao dịch theo source. Mọi lần đổi khóa có trong nhật ký kiểm toán (không kèm giá trị).",
  "bwg.deployTitle": "Một lần khi triển khai: IP của bên gọi",
  "bwg.deployDesc": "Giới hạn theo IP cần backend thấy đúng IP người gọi. Đây là cấu hình hạ tầng, đọc lúc khởi động, nên nằm trong .env của máy chủ (chỉ docker compose; helm/k8s thì không đặt):",
  "bwg.deploySteps": "Lấy subnet bằng docker network inspect <project>_WeKnora-network, rồi tạo lại container app (docker compose up -d --force-recreate app). Kiểm tra: mở trang từ một máy trong LAN, xem client_ip trong log app phải là IP máy đó; nếu mọi request cùng một IP 172.x/192.168.x là sai subnet. Nếu trước frontend còn một load balancer/TLS proxy thì đặt thêm REAL_IP_FROM=<IP hoặc CIDR của LB> và tạo lại container frontend (docker compose up -d --force-recreate frontend).",
  "bwg.fullGuide": "Hướng dẫn đầy đủ kèm xử lý sự cố: docs/billing-payment-webhook.md trong mã nguồn.",
